package com.greenocean.backend.professional.service;
import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;import org.springframework.scheduling.annotation.Scheduled;import com.greenocean.backend.common.exception.*;import java.util.*;
@Service @Transactional public class ProfessionalReminders {
 private final JdbcTemplate db;private final ProfessionalAuthority auth;private final boolean enabled;
 public ProfessionalReminders(JdbcTemplate db,ProfessionalAuthority auth,@Value("${greenocean.clinic.reminders-enabled:false}")boolean enabled){this.db=db;this.auth=auth;this.enabled=enabled;}
 public void preference(UUID who,UUID appointment,boolean enable){auth.actor(who);if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM consultation_requests WHERE id=? AND(requester_user_id=? OR professional_user_id=?))",Boolean.class,appointment,who,who)))throw new NotFoundException("Appointment was not found");db.update("INSERT INTO professional_appointment_reminder_preferences(appointment_id,user_id,enabled) VALUES(?,?,?) ON CONFLICT(appointment_id,user_id) DO UPDATE SET enabled=EXCLUDED.enabled,updated_at=CURRENT_TIMESTAMP",appointment,who,enable);if(!enable)db.update("UPDATE professional_reminder_events SET state='CANCELLED' WHERE appointment_id=? AND recipient_id=? AND state='PENDING'",appointment,who);}
 @Scheduled(fixedDelayString="${greenocean.clinic.reminder-poll-ms:60000}") public void poll(){dispatch();}
 public int dispatch(){if(!enabled)return 0;db.update("INSERT INTO professional_reminder_events(appointment_id,recipient_id,kind,due_at) SELECT c.id,p.user_id,t.kind,c.scheduled_at-t.delay FROM consultation_requests c JOIN professional_appointment_reminder_preferences p ON p.appointment_id=c.id AND p.enabled CROSS JOIN professional_reminder_policy policy CROSS JOIN LATERAL(VALUES('DAY',policy.day_minutes*INTERVAL '1 minute'),('HOUR',policy.hour_minutes*INTERVAL '1 minute'),('QUARTER',policy.quarter_minutes*INTERVAL '1 minute'),('START',INTERVAL '0 minutes')) t(kind,delay) WHERE c.status='CONFIRMED' AND(t.kind<>'START' OR policy.start_enabled) AND c.scheduled_at BETWEEN CURRENT_TIMESTAMP-INTERVAL '2 minutes' AND CURRENT_TIMESTAMP+INTERVAL '30 hours' AND c.scheduled_at-t.delay>=p.updated_at-INTERVAL '2 minutes' AND professional_scope_live(c.professional_user_id,'IR',c.consultation_mode) ON CONFLICT DO NOTHING");int made=0;for(var event:db.queryForList("SELECT e.id,e.recipient_id,(c.status='CONFIRMED' AND pref.enabled AND COALESCE(u.notify_messages,FALSE) AND NOT COALESCE(u.quiet_hours_enabled,TRUE) AND e.due_at>=CURRENT_TIMESTAMP-INTERVAL '2 minutes' AND professional_scope_live(c.professional_user_id,'IR',c.consultation_mode)) AS allowed FROM professional_reminder_events e JOIN consultation_requests c ON c.id=e.appointment_id JOIN professional_appointment_reminder_preferences pref ON pref.appointment_id=e.appointment_id AND pref.user_id=e.recipient_id LEFT JOIN user_preferences u ON u.user_id=e.recipient_id WHERE e.state='PENDING' AND e.due_at<=CURRENT_TIMESTAMP ORDER BY e.due_at,e.id LIMIT 100 FOR UPDATE OF e SKIP LOCKED")){boolean allow=Boolean.TRUE.equals(event.get("allowed"));if(allow){db.update("INSERT INTO notifications(user_id,type,title,body) VALUES(?,'SYSTEM_NOTICE','Service update','Open your private service workspace to view the current status.')",event.get("recipient_id"));made++;}db.update("UPDATE professional_reminder_events SET state=? WHERE id=?",allow?"IN_APP_CREATED":"SUPPRESSED",event.get("id"));}return made;}
}
